// intent: Probes unflatten behavior on a deeply nested key consisting of thousands of /0 tokens to verify linearity.
#include <nlohmann/json.hpp>
#include <iostream>
#include <string>
int main() {
    try {
        std::string long_key;
        for (int i = 0; i < 2000; ++i) {
            long_key += "/0";
        }
        nlohmann::json input = nlohmann::json::object();
        input[long_key] = 42;
        nlohmann::json result = input.unflatten();
        std::cout << result.is_array() << "\n";
    } catch (const std::exception& e) {
        std::cout << e.what() << "\n";
    }
}
